            ))}
          </ul>
        </div>
      </div>

      {/* CHAT WIDGET */}
      <ChatWidget />

      {/* VALUATION MODAL */}
      <ValuationModal isOpen={isValuationOpen} onClose={() => setIsValuationOpen(false)} />
    </div>
  );
};

export default BuyCar;
